 1	class CuttingRod {
 2	    private static final int EMPTY_ROD_REVENUE = 0;
 3	    private static final int FIRST_SELLABLE_LENGTH = 1;
 4	    private static final int SENTINEL_INDEX = 0;
 5	
 6	    static int cutRod(int[] pricesByLength) {
 7	        validatePriceTable(pricesByLength);
 8	        return cutRod(pricesByLength, pricesByLength.length - 1);
 9	    }
10	
11	    static int cutRod(int[] pricesByLength, int rodLength) {
12	        validatePriceTable(pricesByLength);
13	        validateRodLength(pricesByLength, rodLength);
14	
15	        int[] maxRevenue = new int[rodLength + 1];
16	        maxRevenue[SENTINEL_INDEX] = EMPTY_ROD_REVENUE;
17	
18	        for (int currentLength = FIRST_SELLABLE_LENGTH; currentLength <= rodLength; currentLength++) {
19	            maxRevenue[currentLength] = bestRevenueForLength(pricesByLength, maxRevenue, currentLength);
20	        }
21	
22	        return maxRevenue[rodLength];
23	    }
24	
25	    private static void validatePriceTable(int[] pricesByLength) {
26	        if (pricesByLength == null || pricesByLength.length == 0) {
27	            throw new IllegalArgumentException("pricesByLength must include a sentinel value at index 0");
28	        }
29	    }
30	
31	    private static void validateRodLength(int[] pricesByLength, int rodLength) {
32	        if (rodLength < 0 || rodLength >= pricesByLength.length) {
33	            throw new IllegalArgumentException("rodLength must be within the pricesByLength table");
34	        }
35	    }
36	
37	    private static int bestRevenueForLength(int[] pricesByLength, int[] maxRevenue, int currentLength) {
38	        int bestRevenue = EMPTY_ROD_REVENUE;
39	
40	        for (int firstCutLength = FIRST_SELLABLE_LENGTH; firstCutLength <= currentLength; firstCutLength++) {
41	            int remainingLength = currentLength - firstCutLength;
42	            int revenue = pricesByLength[firstCutLength] + maxRevenue[remainingLength];
43	            bestRevenue = Math.max(bestRevenue, revenue);
44	        }
45	
46	        return bestRevenue;
47	    }
48	
49	    public static void main(String[] args) {
50	        int[] pricesByLength = {0, 1, 5, 8, 9, 10, 17, 17, 20};
51	        System.out.println(cutRod(pricesByLength));
52	    }
53	}

